<script setup>
import {computed,onMounted,reactive,ref} from 'vue';
import Icon from '../Icon.vue';
import Modal from '../Modal.vue';
import {api,state,dateTime,notify} from '../../lib';
const items=ref([]),movements=ref([]),tab=ref('stock'),loading=ref(true),busy=ref(false),error=ref(''),formError=ref(''),editing=ref(null),adjusting=ref(null),deleting=ref(null),historyFilter=ref(''),form=reactive({}),adjust=reactive({operation:'add',quantity:1,reason:''});
const low=computed(()=>items.value.filter(x=>x.stock<=x.minimum).length);
const history=computed(()=>movements.value.filter(x=>!historyFilter.value||x.ingredient_id===historyFilter.value));
async function load(){loading.value=true;error.value='';try{[items.value,movements.value]=await Promise.all([api('/admin/ingredients'),api('/admin/stock-movements')]);}catch(e){error.value=e.message;}finally{loading.value=false;}}
onMounted(load);
function edit(item){Object.assign(form,item||{name:'',unit:'kg',stock:0,minimum:1});editing.value=item?.id||'new';formError.value='';}
async function save(){busy.value=true;formError.value='';try{const {stock,...metadata}=form;await api(editing.value==='new'?'/admin/ingredients':`/admin/ingredients/${editing.value}`,{method:editing.value==='new'?'POST':'PUT',body:editing.value==='new'?form:metadata});editing.value=null;await load();notify('Data bahan disimpan.');}catch(e){formError.value=e.message;}finally{busy.value=false;}}
function startAdjust(item){adjusting.value=item;Object.assign(adjust,{operation:'add',quantity:1,reason:''});formError.value='';}
async function saveStock(){busy.value=true;formError.value='';try{await api(`/admin/ingredients/${adjusting.value.id}/stock`,{method:'POST',body:adjust});adjusting.value=null;await load();notify('Stok dan riwayat berhasil diperbarui.');}catch(e){formError.value=e.message;}finally{busy.value=false;}}
async function remove(){busy.value=true;formError.value='';try{await api(`/admin/ingredients/${deleting.value.id}`,{method:'DELETE'});deleting.value=null;await load();notify('Bahan dihapus. Riwayat tetap tersimpan.');}catch(e){formError.value=e.message;}finally{busy.value=false;}}
</script>
<template><div v-if="low" class="stock-warning"><Icon name="AlertCircle"/><div><strong>{{low}} bahan perlu diperiksa</strong><p>Jumlah stok sama dengan atau di bawah batas minimum.</p></div></div><div class="admin-toolbar"><div class="filter-tabs"><button :class="{active:tab==='stock'}" @click="tab='stock'">Daftar bahan</button><button :class="{active:tab==='history'}" @click="tab='history'">Riwayat perubahan</button></div><div class="toolbar-actions"><button class="button secondary" :disabled="loading" @click="load"><Icon name="RefreshCw" :size="16"/>Refresh</button><button v-if="state.user.role==='owner'&&tab==='stock'" class="button primary" @click="edit(null)"><Icon name="Plus" :size="17"/>Tambah bahan</button></div></div><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="loading" class="skeleton table-skeleton"></div><template v-else><div v-if="tab==='stock'" class="table-wrap"><table><thead><tr><th>Bahan baku</th><th>Stok saat ini</th><th>Batas minimum</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{item.name}}</strong></td><td><strong>{{Number(item.stock).toLocaleString('id-ID')}}</strong> {{item.unit}}</td><td>{{item.minimum}} {{item.unit}}</td><td><span :class="['badge',item.stock<=item.minimum?'warning':'success']">{{item.stock<=item.minimum?'Stok menipis':'Cukup'}}</span></td><td><div class="row-actions"><button class="button secondary small-button" @click="startAdjust(item)"><Icon name="Settings2" :size="15"/>Update stok</button><template v-if="state.user.role==='owner'"><button class="icon-button" :aria-label="'Ubah '+item.name" @click="edit(item)"><Icon name="Pencil" :size="16"/></button><button class="icon-button danger" :aria-label="'Hapus '+item.name" @click="deleting=item;formError=''"><Icon name="Trash2" :size="16"/></button></template></div></td></tr><tr v-if="!items.length"><td colspan="5" class="empty-cell">Belum ada bahan. Owner dapat menambahkan bahan pertama.</td></tr></tbody></table></div><template v-else><label class="compact-field">Filter bahan<select v-model="historyFilter"><option value="">Semua bahan</option><option v-for="item in items" :key="item.id" :value="item.id">{{item.name}}</option></select></label><div class="table-wrap"><table><thead><tr><th>Waktu / staf</th><th>Bahan</th><th>Sebelum</th><th>Perubahan</th><th>Sesudah</th><th>Alasan</th></tr></thead><tbody><tr v-for="row in history" :key="row.id"><td>{{dateTime(row.created_at)}}<small>{{row.actor_name}}</small></td><td><strong>{{row.ingredient_name}}</strong></td><td>{{row.before}} {{row.unit}}</td><td :class="row.delta<0?'danger':'green'">{{row.delta>0?'+':''}}{{row.delta}}</td><td>{{row.after}} {{row.unit}}</td><td>{{row.reason}}</td></tr><tr v-if="!history.length"><td colspan="6" class="empty-cell">Belum ada perubahan stok.</td></tr></tbody></table></div></template></template><p class="table-caption">Stok dicatat manual. Pesanan pelanggan tidak mengubah stok bahan baku.</p>
<Modal v-if="editing" :title="editing==='new'?'Tambah bahan baku':'Ubah data bahan'" @close="editing=null"><form @submit.prevent="save"><label>Nama bahan<input v-model="form.name" minlength="2" maxlength="100" required/></label><div class="form-grid"><label>Satuan<select v-model="form.unit"><option v-for="unit in ['kg','gram','liter','ml','pcs','pack']" :key="unit">{{unit}}</option></select></label><label>Batas minimum<input v-model.number="form.minimum" type="number" min="0" max="1000000" step="0.001" required/></label></div><label v-if="editing==='new'">Stok awal<input v-model.number="form.stock" type="number" min="0" max="1000000" step="0.001" required/></label><p v-else class="muted small">Gunakan Update stok untuk mencatat perubahan jumlah beserta alasannya.</p><p v-if="formError" class="alert error" role="alert">{{formError}}</p><div class="modal-actions"><button type="button" class="button secondary" @click="editing=null">Batal</button><button class="button primary" :disabled="busy">Simpan bahan</button></div></form></Modal>
<Modal v-if="adjusting" :title="'Update stok · '+adjusting.name" @close="adjusting=null"><form @submit.prevent="saveStock"><p class="muted">Stok saat ini: <strong>{{adjusting.stock}} {{adjusting.unit}}</strong></p><label>Jenis perubahan<select v-model="adjust.operation"><option value="add">Tambah stok</option><option value="subtract">Kurangi stok</option><option value="set">Tetapkan jumlah stok terbaru</option></select></label><label>Jumlah ({{adjusting.unit}})<input v-model.number="adjust.quantity" type="number" min="0" max="1000000" step="0.001" required/></label><label>Alasan perubahan<textarea v-model="adjust.reason" required minlength="3" maxlength="250" rows="3" placeholder="Misalnya: pembelian bahan, pemakaian, atau rusak"></textarea></label><p v-if="formError" class="alert error" role="alert">{{formError}}</p><div class="modal-actions"><button type="button" class="button secondary" @click="adjusting=null">Batal</button><button class="button primary" :disabled="busy">Simpan perubahan</button></div></form></Modal>
<Modal v-if="deleting" title="Hapus bahan baku?" @close="deleting=null"><p><strong>{{deleting.name}}</strong> akan dihapus dari daftar. Riwayat perubahan tetap tersimpan.</p><p v-if="formError" class="alert error" role="alert">{{formError}}</p><div class="modal-actions"><button class="button secondary" @click="deleting=null">Batal</button><button class="button danger-button" :disabled="busy" @click="remove">Hapus bahan</button></div></Modal>
</template>
